#Requires -Version 7.0
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$StoreReceipt,
    [Parameter(Mandatory)][string]$DesignationSha,
    [switch]$SignSourceAfterApproval
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if (-not $SignSourceAfterApproval) { throw 'HOLD_SOURCE_SIGNING_NOT_APPROVED' }
$hostPath = 'C:\Program Files\PowerShell\7\pwsh.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $hostPath) { throw 'HOLD_UNAPPROVED_HOST' }
$env:PSModulePath = Join-Path $PSHOME 'Modules'
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1')
$signature = Get-AuthenticodeSignature -LiteralPath $hostPath
if ($signature.Status -ne 'Valid' -or
    $signature.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)') { throw 'HOLD_HOST_SIGNATURE' }

if ($StoreReceipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$' -or
    $DesignationSha -cnotmatch '^[a-f0-9]{64}$') { throw 'HOLD_APPROVAL_RECEIPT_FORMAT' }
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
try {
    $expectedSid = ([Security.Principal.NTAccount]::new([Environment]::MachineName, 'windows')).Translate([Security.Principal.SecurityIdentifier])
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    if (-not $expectedSid.Equals($identity.User) -or
        -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'HOLD_SIGNER_TOKEN' }
    $sid = $identity.User.Value
} finally { $identity.Dispose() }
$embeddedAssembly = ''
$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
try { $recordBytes = $type::ReadDesignation($sid, $StoreReceipt, $DesignationSha) }
catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_RECORD_READ_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_RECORD_READ'
}
$utf8 = [Text.UTF8Encoding]::new($false, $true)
$record = $utf8.GetString($recordBytes) | ConvertFrom-Json -AsHashtable
$base = 'F:\study\codex\Project-Limitless\Temp\DiscordUsageDiagnostics20261026'
$candidate = Join-Path $base 'StagingVerifierRelease-3f674efb\candidate\Limitless.StagingVerifier.exe'
$checker = Join-Path $base 'Worktree\Tools\DiscordV2\StagingDraft\Test-ApprovedSigningKey.ps1'
$checkerSha = 'ab57366eef3eefe1e74c6f50cebf440c815d88e6ef8aada2ffa66c616448b24f'
if ($record.Schema -cne 'LIMITLESS_SIGNING_ACCOUNT_DESIGNATION_V1' -or
    $record.Approval -cne 'ISSUE66_SIGNER_DESIGNATION_RECORD_1' -or
    $record.Scope -cne 'ACCOUNT_DESIGNATION_ONLY' -or $record.Account -cne 'windows' -or
    $record.AccountSid -cne $sid -or $record.KeyCheckScriptPath -ine $checker -or
    $record.KeyCheckScriptSha256 -cne $checkerSha -or $record.CandidatePath -ine $candidate -or
    $record.CandidateSha256 -cne '145f3921e88ab2caba98afd4c5bb39eb7f9706aa6ad5e3fca5d5891f9f73adbb' -or
    $record.CertificateThumbprint -cne '437423567AD4B703578F231E34A06592B38DB4EB' -or
    $record.CertificateDerSha256 -cne '7dba5310d6ded0035595e5e7ab8b8b73422f2925b49c633426995c322940672c' -or
    $record.RsaSpkiSha256 -cne '2a6d0a7d31e7642df209b6cbe12fa628500663f540eb6bd557cac2aca2d31f7c') {
    throw 'HOLD_DESIGNATION_BINDING'
}

$source = Join-Path $base 'Worktree\Tools\DiscordV2\StagingDraft\StagingSource.Candidate.ps1'
$unsignedSha = '9007a8cface8955d645b3aa7821bd0084cbf0df21ccb51093575ddbde2a8d7e8'
$expectedVerifierSha = '86ba45f0139122f80c1cfb9492700edb9a537e63bd9ee511ac9231e34fb3d7ca'
$thumb = $record.CertificateThumbprint
$shaAlgorithm = [Security.Cryptography.HashAlgorithmName]::SHA256
$pss = [Security.Cryptography.RSASignaturePadding]::Pss
function BytesSha([byte[]]$b) {
    [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($b)).ToLowerInvariant()
}
function Read-SourceBytes([IO.Stream]$stream) {
    if ($stream.Length -lt 1 -or $stream.Length -gt 1048576) { throw 'HOLD_SOURCE_SIZE' }
    $bytes = [byte[]]::new([int]$stream.Length)
    $stream.ReadExactly($bytes)
    return ,$bytes
}
function Assert-Signer($cert) {
    $time = Get-Date
    $eku = @($cert.Extensions | Where-Object { $_ -is [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension] } |
        ForEach-Object EnhancedKeyUsages | ForEach-Object Value)
    if ($cert.Thumbprint -cne $thumb -or
        $cert.GetCertHashString($shaAlgorithm).ToLowerInvariant() -cne $record.CertificateDerSha256 -or
        $eku -notcontains '1.3.6.1.5.5.7.3.3' -or $time -lt $cert.NotBefore -or $time -ge $cert.NotAfter) {
        throw 'HOLD_SOURCE_CERTIFICATE'
    }
}
function Require-ProtectedVerifier($verifier, [string]$image, [string]$digest) {
    $verifier.Check()
    $info = [Diagnostics.ProcessStartInfo]::new()
    $info.FileName = $verifier.FilePath
    $info.WorkingDirectory = Split-Path -Parent $verifier.FilePath
    $info.UseShellExecute = $false
    $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true
    $info.RedirectStandardError = $true
    $info.Environment.Clear()
    $info.Environment['SystemRoot'] = 'C:\Windows'
    $info.Environment['WINDIR'] = 'C:\Windows'
    $info.Environment['SystemDrive'] = 'C:'
    $info.Environment['PATH'] = 'C:\Windows\System32'
    $info.Environment['DOTNET_ROOT'] = 'C:\Program Files\dotnet'
    $info.Environment['DOTNET_ROOT_X64'] = 'C:\Program Files\dotnet'
    $info.Environment['DOTNET_ROLL_FORWARD'] = 'LatestPatch'
    foreach ($value in @('--verify-image',$image,$digest)) { $info.ArgumentList.Add($value) }
    $process = [Diagnostics.Process]::Start($info)
    if ($null -eq $process) { throw 'HOLD_SOURCE_VERIFIER_START' }
    try {
        $output = $process.StandardOutput.ReadToEndAsync()
        $errors = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit(20000)) { $process.Kill($true); throw 'HOLD_SOURCE_VERIFIER_TIMEOUT' }
        if ($process.ExitCode -ne 0 -or $output.GetAwaiter().GetResult().Trim() -cne 'VERIFIED_IMAGE_ONLY' -or
            $errors.GetAwaiter().GetResult().Trim().Length -ne 0) { throw 'HOLD_SOURCE_VERIFIER_DENIED' }
    } finally { $process.Dispose() }
}

$inputStream = [IO.File]::Open($source, 'Open', 'Read', 'Read')
try { $unsigned = Read-SourceBytes $inputStream } finally { $inputStream.Dispose() }
if ((BytesSha $unsigned) -cne $unsignedSha) { throw 'HOLD_UNSIGNED_SOURCE_SHA' }

$verifier = [Activator]::CreateInstance($type.GetNestedType('SignedVerifierSource'))
try {
    if ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($verifier.Stream)).ToLowerInvariant() -cne $expectedVerifierSha) {
        throw 'HOLD_PROTECTED_VERIFIER_SHA'
    }
    $cert = Get-Item -LiteralPath "Cert:\LocalMachine\My\$thumb"
    try {
        Assert-Signer $cert
        $private = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($cert)
        if ($null -eq $private) { throw 'HOLD_SOURCE_KEY_ACCESS' }
        try {
            if ($private -isnot [Security.Cryptography.RSACng] -or
                $private.Key.ExportPolicy -ne [Security.Cryptography.CngExportPolicies]::None -or
                (BytesSha ($private.ExportSubjectPublicKeyInfo())) -cne $record.RsaSpkiSha256) {
                throw 'HOLD_SOURCE_KEY_BINDING'
            }
            $start = [DateTimeOffset]::UtcNow
            $end = $start.AddMinutes(5)
            $workspace = [Activator]::CreateInstance($type.GetNestedType('SigningWorkspace'),
                [object[]]@($sid,$start,$end,$false))
            try {
                $workspace.CopyVerifiedBytes('StagingSource.ps1',$unsigned)
                $target = Join-Path $workspace.DirectoryPath 'StagingSource.ps1'
                $proof = $workspace.OpenVerifiedFile('StagingSource.ps1')
                try { if ((BytesSha (Read-SourceBytes $proof)) -cne $unsignedSha) { throw 'HOLD_PROTECTED_SOURCE_SHA' } }
                finally { $proof.Dispose() }
                if ((Get-AuthenticodeSignature -LiteralPath $target).Status -ne 'NotSigned' -or
                    [DateTimeOffset]::UtcNow -ge $end) { throw 'HOLD_SOURCE_SIGN_PRECHECK' }
                $workspace.MarkSigningAttempt()
                $null = Set-AuthenticodeSignature -LiteralPath $target -Certificate $cert -HashAlgorithm SHA256 -IncludeChain Signer
                $signed = $workspace.OpenVerifiedFile('StagingSource.ps1')
                try {
                    $finalBytes = Read-SourceBytes $signed
                    $sourceSha = BytesSha $finalBytes
                    if ($sourceSha -ceq $unsignedSha) { throw 'HOLD_SOURCE_UNCHANGED' }
                    $signature = Get-AuthenticodeSignature -LiteralPath $target
                    if ($signature.Status -ne 'Valid' -or $null -eq $signature.SignerCertificate) { throw 'HOLD_SOURCE_AUTHENTICODE' }
                    Assert-Signer $signature.SignerCertificate
                    $public = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($signature.SignerCertificate)
                    if ($null -eq $public) { throw 'HOLD_SOURCE_PUBLIC_KEY' }
                    try {
                        if ((BytesSha ($public.ExportSubjectPublicKeyInfo())) -cne $record.RsaSpkiSha256) { throw 'HOLD_SOURCE_SPKI' }
                        Require-ProtectedVerifier $verifier $target $sourceSha
                        if ([DateTimeOffset]::UtcNow -ge $end) { throw 'HOLD_PSS_WINDOW' }
                        $detached = $private.SignData($finalBytes, $shaAlgorithm, $pss)
                        if (-not $public.VerifyData($finalBytes, $detached, $shaAlgorithm, $pss)) { throw 'HOLD_SOURCE_PSS' }
                        $workspace.CopyVerifiedBytes('StagingSource.sig', $detached)
                        $sigCopy = $workspace.OpenVerifiedFile('StagingSource.sig')
                        try {
                            $finalSig = Read-SourceBytes $sigCopy
                            $signed.Position = 0
                            $readback = Read-SourceBytes $signed
                            if ((BytesSha $readback) -cne $sourceSha -or
                                (BytesSha $finalSig) -cne (BytesSha $detached) -or
                                -not $public.VerifyData($readback, $finalSig, $shaAlgorithm, $pss)) {
                                throw 'HOLD_SOURCE_PSS_READBACK'
                            }
                            $workspace.Check()
                            $verifier.Check()
                            'STAGING_SOURCE_AUTHENTICODE_AND_PSS_VERIFIED'
                            "SIGNED_SOURCE_SHA256=$sourceSha"
                            "DETACHED_SIGNATURE_SHA256=$(BytesSha $finalSig)"
                        } finally { $sigCopy.Dispose() }
                    } finally { $public.Dispose() }
                } finally { $signed.Dispose() }
            } finally { $workspace.Dispose() }
        } finally { $private.Dispose() }
    } finally { $cert.Dispose() }
} finally { $verifier.Dispose() }
